import ballerina/io;

public function main() {
    int[] xs = [1, 2, 3];
    int n = from var x in xs
        let int y = x * 2
        collect y.length();
    io:println(n);

    int[] r = from var x in xs
        let int n2 = x + 10
        group by x
        select n2[0] + n2.length();
    io:println(r);
}
